// Generated by tools/generate-web-color-profiles.py from public color-space definitions.
// Fixed creation date; no platform profile is copied.
const profiles = {
  'srgb': '',
  'display-p3': '',
}
export function iccProfile(colorSpace) {
  const encoded = profiles[colorSpace]
  if (!encoded) throw new Error('Unsupported TIFF color space.')
  return Uint8Array.from(atob(encoded), (c) => c.charCodeAt(0))
}
